const $=s=>document.querySelector(s), app=$('#app');
const TYPES=['SOS / Personal Safety','Medical Emergency','Fire','Harassment or Threat','Suspicious Activity','Accident','Unsafe Location','Other Emergency'];
let SOS_PHONE='8531996611';
const TYPE_ICONS={'SOS / Personal Safety':'🆘','Medical Emergency':'✚','Fire':'♨','Harassment or Threat':'◉','Suspicious Activity':'⌕','Accident':'⚠','Unsafe Location':'⌖','Other Emergency':'⋯'};
let token=localStorage.getItem('campus_token')||'', user=JSON.parse(localStorage.getItem('campus_user')||'null'), page='dashboard', incidents=[], dashboard={}, selected=null, currentIncident=null, type='SOS / Personal Safety', recorder=null, audioChunks=[], sosCapture=null;
const cancelledCaptures=new Set();
new MutationObserver(()=>{const caption=$('.profile-mini small');if(user?.role==='student'&&caption){const number=user.register_number||user.student_id||'Student';if(caption.textContent!==number)caption.textContent=number}document.querySelectorAll('.info-label').forEach(x=>{if(x.textContent.trim()==='Student ID')x.textContent='Register number'});$('#record-audio')?.remove();document.querySelectorAll('.detail-section p').forEach(x=>{if(x.textContent.startsWith('Recording begins only after'))x.textContent='SOS automatically records audio and video and captures one photo after camera and microphone permission. Evidence appears here while it is captured; use the red banner to stop recording.'})}).observe(app,{childList:true,subtree:true});
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials=s=>String(s||'CS').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const fmtTime=s=>s?new Date(s).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}):'—';
const fmtDate=s=>s?new Date(s).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'—';
async function api(path,opts={}){const r=await fetch(path,{...opts,headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`} :{}),...(opts.headers||{})}});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.error||`Request failed (${r.status})`);return d}
function toast(msg,error=false){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=msg;document.body.append(el);setTimeout(()=>el.remove(),3500)}
function statusPill(s){return `<span class="status status-${esc(s)}">${esc(s)}</span>`}
function login(mode='admin',notice=''){const register=mode==='register',student=mode==='student'||register;const emailValue=student?'':'admin@campus.edu';app.innerHTML=`<main class="login-wrap"><section class="login-card"><div class="brand"><span class="brand-mark">+</span><div><div class="brand-name">Campus Safety</div><div class="brand-sub">Response Center</div></div></div><div class="eyebrow">SECURE CAMPUS ACCESS</div><h1>${register?'Create student account':student?'Student sign in':'Admin sign in'}</h1><p>${register?'Register with your campus details to create a student account.':student?'Sign in to view your safety home and incident history.':'Administrator access to the campus response dashboard.'}</p><div class="auth-tabs"><button data-auth-mode="admin" class="${mode==='admin'?'active':''}">Admin login</button><button data-auth-mode="student" class="${mode==='student'?'active':''}">Student login</button><button data-auth-mode="register" class="${register?'active':''}">Student register</button></div>${notice?`<div class="soft-alert" style="margin:12px 0">${esc(notice)}</div>`:''}<form class="login-form" id="auth-form">${register?`<label for="name">Full name</label><input id="name" autocomplete="name" maxlength="120" required><label for="register-number">Register number</label><input id="register-number" autocomplete="off" maxlength="32" placeholder="e.g. STU-9B16B8EE" required><label for="department">Department</label><input id="department" maxlength="120" required><label for="phone">Phone number</label><input id="phone" type="tel" autocomplete="tel" required><label for="year">Year of study</label><select id="year" required><option value="">Select your year</option>${['1st Year','2nd Year','3rd Year','4th Year','5th Year','6th Year','Postgraduate','Other'].map(y=>`<option>${y}</option>`).join('')}</select>`:''}<label for="email">${student?'Student email':'Admin email'}</label><input id="email" type="email" autocomplete="username" value="${esc(localStorage.getItem(student?'campus_student_email':'campus_admin_email')||emailValue)}" required><label for="password">Password${register?' (at least 8 characters)':''}</label><input id="password" type="password" autocomplete="${register?'new-password':'current-password'}" ${register?'minlength="8"':''} required><button class="btn btn-primary" type="submit">${register?'Create student account':'Sign in'} <span>→</span></button></form><div class="demo-note"><b>Local admin access</b><br>Admin: admin@campus.edu<br>Password: CampusSafe2026!<br>Register a student account to enable student login.</div></section></main>`;document.querySelectorAll('[data-auth-mode]').forEach(b=>b.onclick=()=>login(b.dataset.authMode));$('#auth-form').onsubmit=async e=>{e.preventDefault();try{if(register){const d=await api('/api/auth/register',{method:'POST',body:JSON.stringify({name:$('#name').value,register_number:$('#register-number').value,department:$('#department').value,phone:$('#phone').value,year_of_study:$('#year').value,email:$('#email').value,password:$('#password').value})});localStorage.setItem('campus_student_email',$('#email').value);login('student',d.message);toast('Student registration saved. Please sign in.');return}const d=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email:$('#email').value,password:$('#password').value,expected_role:student?'student':'administrator'})});token=d.token;user=d.user;localStorage.setItem('campus_token',token);localStorage.setItem('campus_user',JSON.stringify(user));localStorage.setItem(student?'campus_student_email':'campus_admin_email',$('#email').value);const profile=await api('/api/me');SOS_PHONE=profile.contacts?.[0]?.phone||SOS_PHONE;page=user.role==='student'?'student':'dashboard';await render()}catch(e){toast(e.message,true)}}}
function shell(content){const student=user.role==='student';const nav=student?[['student','⌂','Safety home'],['incidents','▤','My incidents']]:[['dashboard','◫','Overview'],['incidents','▤','Incidents'],['notifications','♧','Notifications'],['reports','▥','Reports & insights'],['audit','☷','Audit history']];return `<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">+</span><div><div class="brand-name">Campus Safety</div><div class="brand-sub">Response Center</div></div></div><div class="nav-label">Workspace</div><nav class="nav">${nav.map(([p,i,n])=>`<button class="${page===p?'active':''}" data-page="${p}"><span class="nav-ico">${i}</span>${n}${p==='incidents'&&dashboard.metrics?.awaiting?`<span class="nav-count">${dashboard.metrics.awaiting}</span>`:''}</button>`).join('')}</nav><div class="side-bottom">${!student?`<div class="nav-label">Emergency contact</div><div class="call-card"><small>Primary response line</small><div class="call-number">${esc(SOS_PHONE)}</div><div class="call-help">Configured campus emergency contact<br>Keep this line available during a response.</div></div>`:''}<div class="profile-mini"><span class="avatar">${initials(user.name)}</span><div><b>${esc(user.name)}</b><small>${esc(user.role.replace('_',' '))}</small></div><button class="logout" title="Sign out" id="logout">↗</button></div></div></aside><main class="main"><header class="topbar"><div class="crumb"><button class="icon-btn mobile-menu" onclick="toast('Navigation available on desktop sidebar')">☰</button>Campus Safety <span> / </span><strong>${esc(pageLabel())}</strong></div><div class="top-actions"><span class="live-pill"><i class="dot"></i> System operational</span><button class="icon-btn" id="bell" title="Notifications">♧<i class="unread"></i></button><button class="btn btn-sm top-signout" id="logout-top">Sign out <span>↗</span></button><span class="avatar">${initials(user.name)}</span></div></header><div class="workspace">${content}</div></main></div>`}
function pageLabel(){return selected?'Incident details':({dashboard:'Overview',incidents:user.role==='student'?'My incidents':'Incidents',notifications:'Notifications',reports:'Reports & insights',audit:'Audit history',student:'Safety home'}[page]||'Overview')}
function metrics(){const m=dashboard.metrics||{};return `<section class="metric-grid"><article class="metric-card"><div class="metric-top">Active emergencies<span class="metric-icon" style="background:#fff0ed;color:#d94239">!</span></div><div class="metric-value">${m.active||0}</div><div class="metric-foot">Incidents needing active response</div></article><article class="metric-card"><div class="metric-top">Today's incidents<span class="metric-icon" style="background:#edf5f9;color:#42718a">◷</span></div><div class="metric-value">${m.today||0}</div><div class="metric-foot">Reported since midnight</div></article><article class="metric-card"><div class="metric-top">Awaiting response<span class="metric-icon" style="background:#fff5e3;color:#bd791b">⌛</span></div><div class="metric-value">${m.awaiting||0}</div><div class="metric-foot">Not yet acknowledged</div></article><article class="metric-card"><div class="metric-top">Resolved today<span class="metric-icon" style="background:#e8f4eb;color:#398358">✓</span></div><div class="metric-value">${m.resolved||0}</div><div class="metric-foot">${m.total||0} all time · ${m.cancelled||0} cancelled</div></article></section>`}
function reportMetrics(){const m=dashboard.metrics||{},dur=s=>`${String(Math.floor((s||0)/60)).padStart(2,'0')}:${String((s||0)%60).padStart(2,'0')}`;return `<section class="metric-grid"><article class="metric-card"><div class="metric-top">Total incidents</div><div class="metric-value">${m.total||0}</div><div class="metric-foot">All time</div></article><article class="metric-card"><div class="metric-top">Active</div><div class="metric-value">${m.active||0}</div><div class="metric-foot">Currently open</div></article><article class="metric-card"><div class="metric-top">Resolved</div><div class="metric-value">${m.resolved_total||0}</div><div class="metric-foot">All time</div></article><article class="metric-card"><div class="metric-top">Cancelled</div><div class="metric-value">${m.cancelled||0}</div><div class="metric-foot">Preserved in audit history</div></article><article class="metric-card"><div class="metric-top">Avg. response time</div><div class="metric-value">${dur(m.avg_response_seconds)}</div><div class="metric-foot">Minutes : seconds</div></article><article class="metric-card"><div class="metric-top">Avg. resolution time</div><div class="metric-value">${dur(m.avg_resolution_seconds)}</div><div class="metric-foot">Minutes : seconds</div></article></section>`}
function emergencyCard(i){return `<div class="emergency-row" data-open="${esc(i.id)}"><span class="event-icon" style="background:#fff0ed;color:#d94239">${TYPE_ICONS[i.incident_type]||'!'}</span><div><div class="event-title">${esc(i.incident_type)} <span style="color:#a0aaa3;font-weight:500">· ${esc(i.student_name)}</span></div><div class="event-location">⌖ ${esc(i.location_name||'Location pending')} · ${esc(i.id)}</div></div>${statusPill(i.status)}<span class="event-time">${fmtTime(i.started_at)}</span></div>`}
function activity(){const all=incidents.flatMap(i=>(i.timeline||[]).map(e=>({...e,incident:i})));all.sort((a,b)=>b.created_at.localeCompare(a.created_at));return all.slice(0,5).map(e=>`<div class="feed-item"><div class="feed-rail"><i class="feed-dot"></i><i class="feed-line"></i></div><div class="feed-copy"><b>${esc(e.event_type.replaceAll('_',' '))}</b> · ${esc(e.incident.student_name)}<time>${fmtTime(e.created_at)} · ${esc(e.incident.id)}</time></div></div>`).join('')||'<div class="empty">New incident activity will appear here.</div>'}
function chart(){const a=dashboard.categories||[], max=Math.max(1,...a.map(x=>x.value));const labels=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];return `<div class="bars">${labels.map((l,i)=>{const v=a[i%Math.max(1,a.length)]?.value||0;return `<div class="bar-wrap"><div class="bar ${i===3?'hot':''}" style="height:${Math.max(5,Math.min(105,v/max*100))}px"></div><span class="bar-label">${l}</span></div>`}).join('')}</div><div class="chart-legend"><span><i class="legend-dot"></i>Incidents by category · ${a.reduce((n,x)=>n+x.value,0)} total</span></div>`}
function locations(){const a=dashboard.locations||[],max=Math.max(1,...a.map(x=>x.value));return `<div class="location-bars">${a.map(x=>`<div class="location-line"><span>${esc(x.name||'Unspecified')}</span><div class="location-track"><div class="location-fill" style="width:${x.value/max*100}%"></div></div><b>${x.value}</b></div>`).join('')||'<div class="empty">No location data yet.</div>'}</div>`}
function table(rows=incidents){return `<div class="table-card card"><div class="card-head"><div><h2>${user.role==='student'?'My incident history':'All incidents'}</h2><p>${rows.length} incident${rows.length===1?'':'s'} in this view</p></div><button class="btn btn-sm" id="refresh">↻ &nbsp;Refresh</button></div><div class="table-toolbar"><input class="searchbox" id="search" placeholder="⌕  Search student or ID…"><select class="filter" id="status-filter"><option value="">All statuses</option>${['active','acknowledged','responding','resolved','cancelled'].map(x=>`<option>${x}</option>`).join('')}</select><select class="filter" id="type-filter"><option value="">All emergency types</option>${TYPES.map(x=>`<option>${esc(x)}</option>`).join('')}</select><select class="filter" id="officer-filter"><option value="">All officers</option><option>Maya Rao</option></select></div><div class="table-scroll"><table class="incident-table"><thead><tr><th>Incident</th><th>Student</th><th>Emergency type</th><th>Location</th><th>Assigned officer</th><th>Reported</th><th>Status</th></tr></thead><tbody>${rows.map(i=>`<tr data-open="${esc(i.id)}"><td><span class="incident-id">${esc(i.id)}</span></td><td><div class="person-cell"><span class="avatar">${initials(i.student_name)}</span><span><b>${esc(i.student_name)}</b><small>${esc(i.student_id||'Student')}</small></span></div></td><td><span class="type-pill">${TYPE_ICONS[i.incident_type]||'•'} &nbsp;${esc(i.incident_type)}</span></td><td>${esc(i.location_name||'Pending')}</td><td>${esc(i.assigned_to||'—')}</td><td>${fmtDate(i.started_at)} · ${fmtTime(i.started_at)}</td><td>${statusPill(i.status)}</td></tr>`).join('')||`<tr><td colspan="7"><div class="empty">No incidents match these filters.</div></td></tr>`}</tbody></table></div></div>`}
function dashboardPage(){const active=incidents.filter(i=>['active','acknowledged','responding'].includes(i.status));return `<div class="page-head"><div><div class="eyebrow">CAMPUS RESPONSE CENTER</div><h1>Good ${new Date().getHours()<12?'morning':new Date().getHours()<17?'afternoon':'evening'}, ${esc(user.name.split(' ')[0])}</h1><p class="subhead">Here’s the live safety picture across your campus.</p></div><span class="date-tag">${new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long'})}</span></div>${metrics()}<div class="dashboard-grid"><section class="card"><div class="card-head"><div><h2>Active emergencies</h2><p>Live incidents requiring attention</p></div><button class="section-link" data-page="incidents">View all →</button></div><div class="card-body">${active.length?`<div class="priority-banner"><i class="priority-bubble"></i><div class="priority-text"><b>${dashboard.metrics?.awaiting||0} awaiting acknowledgement</b><br>Review new alerts and assign a response officer.</div></div><div class="emergency-list">${active.slice(0,4).map(emergencyCard).join('')}</div>`:`<div class="empty">No active emergencies. Campus response is clear.</div>`}</div></section><section class="card"><div class="card-head"><div><h2>Response activity</h2><p>Recent incident timeline</p></div><button class="section-link" data-page="incidents">Timeline →</button></div><div class="card-body"><div class="feed">${activity()}</div></div></section></div><div class="dashboard-grid" style="margin-top:17px"><section class="card chart-card"><div class="card-head"><div><h2>Incident activity</h2><p>Category distribution across reported incidents</p></div><span class="type-pill">All time</span></div>${chart()}</section><section class="card"><div class="card-head"><div><h2>Campus locations</h2><p>Reports grouped by location</p></div></div>${locations()}</section></div>${table(incidents.slice(0,5))}`}
function incidentsPage(){return `<div class="page-head"><div><div class="eyebrow">RESPONSE MANAGEMENT</div><h1>${user.role==='student'?'My incidents':'Incident management'}</h1><p class="subhead">Review alerts, track response status, and open incident timelines.</p></div></div>${table()}`}
function studentPage(){const queued=JSON.parse(localStorage.getItem('campus_pending_alerts')||'[]');return `<div class="student-view"><div class="student-top"><div><div class="eyebrow">CAMPUS SAFETY</div><h1>You're not alone.</h1></div><span class="live-pill"><i class="dot"></i> Campus safety online</span></div>${queued.length?`<div class="priority-banner"><i class="priority-bubble"></i><div class="priority-text"><b>Alert not yet delivered</b><br>Your SOS is saved on this device and will retry when this page reconnects. Call ${esc(SOS_PHONE)} directly if you need immediate help.</div></div>`:''}<section class="student-hero"><div><span class="student-hello">Hello, ${esc(user.name.split(' ')[0])}</span><h2>Do you need help right now?</h2><p>Press SOS to alert campus security immediately. Your incident is sent first. Location can be shared if you allow it, and you can add details after.</p><div class="call-strip"><div><small>Direct campus emergency line</small><b>☎ &nbsp;${esc(SOS_PHONE)}</b></div><a class="btn btn-sm" href="tel:${esc(SOS_PHONE)}">Call now</a></div></div><div class="sos-zone"><button class="sos-button" id="sos">SOS</button><span class="sos-help">PRESS FOR HELP</span><span class="sos-disclaimer">Your alert is sent to authorized campus responders. Do not use this service for general enquiries.</span></div></section><div class="student-lower"><section class="card"><div class="card-head"><div><h2>What kind of help?</h2><p>Optional — SOS is always the fastest option</p></div></div><div class="card-body"><div class="category-grid">${TYPES.map(t=>`<button class="category ${t===type?'selected':''}" data-type="${esc(t)}"><span>${TYPE_ICONS[t]}</span>${esc(t.replace(' / ','/'))}</button>`).join('')}</div></div></section><section class="card profile-card"><h3>Your campus profile</h3><div class="profile-info"><div><div class="info-label">Student</div><div class="info-value">${esc(user.name)}</div></div><div><div class="info-label">Student ID</div><div class="info-value">${esc(user.student_id)}</div></div><div><div class="info-label">Department</div><div class="info-value">${esc(user.department)}</div></div><div><div class="info-label">Account status</div><div class="info-value" style="color:#398358">● Active</div></div></div><div class="detail-section"><div class="soft-alert"><b>When you activate SOS</b>Campus security is notified right away. Location sharing and media evidence are subject to your device permissions and campus privacy policy.</div></div></section></div><div style="margin-top:17px">${table(incidents.slice(0,4))}</div></div>`}
function detailPage(i){const canAct=user.role!=='student';const tl=(i.timeline||[]).slice().reverse();const hasLocation=i.latitude!==null&&i.latitude!==undefined&&i.longitude!==null&&i.longitude!==undefined&&Number.isFinite(Number(i.latitude))&&Number.isFinite(Number(i.longitude));const mapsUrl=hasLocation?`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${i.latitude},${i.longitude}`)}`:'';return `<div class="page-head"><div><button class="section-link" id="back">← &nbsp;Back to ${user.role==='student'?'my incidents':'incidents'}</button><div class="eyebrow" style="margin-top:15px">INCIDENT RESPONSE</div><h1>${esc(i.incident_type)}</h1><p class="subhead">${esc(i.id)} &nbsp;·&nbsp; Reported ${fmtDate(i.started_at)} at ${fmtTime(i.started_at)}</p></div>${statusPill(i.status)}</div><div class="incident-detail"><div class="card detail-card"><div class="detail-head"><div><h2>${esc(i.student_name)}</h2><div class="detail-id">${esc(i.student_id||'Student')} · ${esc(i.department||'—')}</div></div><div class="detail-actions">${canAct&&i.status==='active'?'<button class="btn btn-primary btn-sm" data-action="acknowledge">✓ Acknowledge</button>':''}${canAct&&i.status!=='resolved'&&i.status!=='cancelled'?'<button class="btn btn-sm" data-action="assign">↗ Assign officer</button>':''}${canAct&&['active','acknowledged'].includes(i.status)?'<button class="btn btn-sm" data-action="respond">Responding</button>':''}${canAct&&i.status==='responding'?'<button class="btn btn-sm" data-action="arrive">Officer arrived</button>':''}${canAct&&!['resolved','cancelled'].includes(i.status)?'<button class="btn btn-primary btn-sm" data-action="resolve">Resolve</button>':''}${user.role==='student'&&['active','acknowledged'].includes(i.status)?'<button class="btn btn-danger btn-sm" data-action="cancel">Cancel alert</button>':''}</div></div><div class="detail-section"><h3>Student information</h3><div class="detail-grid"><div><div class="info-label">Phone</div><div class="info-value">${esc(i.phone||'—')}</div></div><div><div class="info-label">Department</div><div class="info-value">${esc(i.department||'—')}</div></div><div><div class="info-label">Assigned officer</div><div class="info-value">${esc(i.assigned_to||'Awaiting assignment')}</div></div><div><div class="info-label">Emergency type</div><div class="info-value">${esc(i.incident_type)}</div></div><div><div class="info-label">Incident status</div><div class="info-value">${esc(i.status)}</div></div><div><div class="info-label">Description</div><div class="info-value">${esc(i.description||'No additional details')}</div></div></div></div><div class="detail-section"><h3>Available location</h3><div class="map-placeholder"><span class="map-marker">⌖ &nbsp;${hasLocation?`${Number(i.latitude).toFixed(6)}, ${Number(i.longitude).toFixed(6)}`:esc(i.location_name||'Location pending')}</span></div>${hasLocation?`<p style="font-size:10px;color:#68776e;margin-top:9px">${esc(i.location_name||'Device GPS fix')} · GPS accuracy ±${i.accuracy?Math.round(i.accuracy)+' m':'unknown'} · ${fmtTime(i.updated_at)}</p><a class="btn btn-sm" style="margin-top:9px" href="${esc(mapsUrl)}" target="_blank" rel="noopener noreferrer">Open exact pin in Google Maps ↗</a>`:`<p style="font-size:10px;color:#9aa39d;margin-top:9px">Waiting for the student to grant location permission.</p>`}<div class="detail-grid" style="margin-top:12px"><div><div class="info-label">Latitude</div><div class="info-value">${i.latitude??'Not available'}</div></div><div><div class="info-label">Longitude</div><div class="info-value">${i.longitude??'Not available'}</div></div><div><div class="info-label">Accuracy</div><div class="info-value">${i.accuracy?`${Math.round(i.accuracy)} m`:'Not available'}</div></div></div></div><div class="detail-section"><h3>Evidence</h3><div class="tabs">${['All','Audio','Photos','Video','Notes'].map((x,n)=>`<button class="tab ${n===0?'active':''}" data-evidence-tab="${x}">${x}</button>`).join('')}</div><div id="evidence-list">${evidenceList(i.evidence||[],'All')}</div>${user.role==='student'?'<div style="display:flex;gap:7px;flex-wrap:wrap;margin-top:11px"><button class="btn btn-sm" id="add-note">＋ Add a note</button><button class="btn btn-sm" id="record-audio">● Record audio</button><button class="btn btn-sm" id="upload-photo">▧ Add photo/video</button><input id="media-file" type="file" accept="image/*,video/*,audio/*" capture="environment" hidden></div><p style="font-size:9px;color:#929d96;line-height:1.5;margin-top:8px">Recording begins only after you grant microphone permission. A visible indicator stays active while recording. Files are private to this incident.</p>':''}</div></div><div style="display:grid;gap:17px"><section class="card detail-card"><h3 style="font-size:13px;margin-bottom:15px">Incident timeline</h3><div class="timeline">${tl.map(e=>`<div class="timeline-row"><span class="timeline-time">${fmtTime(e.created_at)}</span><span class="timeline-rail"><i class="timeline-node"></i><i class="timeline-stem"></i></span><span class="timeline-text"><b>${esc(e.event_type.replaceAll('_',' '))}</b>${esc(e.description)}<br><span style="color:#a0aaa4">${esc(e.actor_name||'System')}</span></span></div>`).join('')}</div></section><section class="card detail-card"><h3 style="font-size:13px;margin-bottom:12px">Emergency call</h3>${(i.calls||[]).map(c=>`<div class="evidence-row"><span class="evidence-icon">☎</span><span><b>${esc(c.phone_number)}</b><small>${fmtTime(c.started_at)} · Campus emergency line</small></span><span class="evidence-state">${esc(c.call_status)}</span></div>`).join('')||'<p class="subhead">No call record.</p>'}<p style="font-size:10px;color:#929d96;line-height:1.5;margin-top:11px">Dashboard and incident record remain the primary source of emergency information.</p></section><section class="card detail-card"><h3 style="font-size:13px;margin-bottom:10px">Notifications</h3>${(i.notifications||[]).map(n=>`<div class="evidence-row"><span class="evidence-icon">♧</span><span><b>${esc(n.title)}</b><small>${esc(n.message)}</small></span><span class="evidence-state">${esc(n.status)}</span></div>`).join('')||'<p class="subhead">No notification records.</p>'}</section></div></div>`}
function evidenceList(a,filter){const map={Audio:'audio',Photos:'photo',Video:'video',Notes:'text'};const x=a.filter(e=>filter==='All'||e.type===map[filter]);return x.length?x.map(e=>`<div class="evidence-row"><span class="evidence-icon">${e.type==='audio'?'♫':e.type==='video'?'▶':e.type==='photo'?'▧':'✎'}</span><span><b>${esc(e.filename)}</b><small>${esc(e.type)} · ${fmtTime(e.created_at)} · ${e.file_size?`${Math.ceil(e.file_size/1024)} KB`:e.upload_status==='recording'?'Capture in progress':'Waiting for capture'}</small></span>${e.upload_status==='uploaded'?`<button class="btn btn-sm" data-preview="${esc(e.id)}" data-preview-type="${esc(e.type)}">Preview</button><button class="btn btn-sm" data-download="${esc(e.id)}">Download</button>`:`<span class="evidence-state">${esc(e.upload_status==='recording'?'Recording':e.upload_status==='uploading'?'Uploading':e.upload_status)}</span>`}</div>`).join(''):'<div class="empty" style="padding:20px">No evidence in this section.</div>'}
function notificationsPage(){const all=incidents.flatMap(i=>(i.notifications||[]).map(n=>({...n,incident:i}))).sort((a,b)=>b.sent_at.localeCompare(a.sent_at));return `<div class="page-head"><div><div class="eyebrow">ALERT DELIVERY</div><h1>Notifications</h1><p class="subhead">In-app alert records associated with emergency incidents.</p></div></div><div class="card detail-card">${all.map(n=>`<div class="evidence-row" style="padding:14px 2px;cursor:pointer" data-open="${esc(n.incident.id)}"><span class="evidence-icon">♧</span><span><b>${esc(n.title)} · ${esc(n.incident.student_name)}</b><small>${esc(n.message)} · ${fmtDate(n.sent_at)} ${fmtTime(n.sent_at)}</small></span><span class="evidence-state">${esc(n.status)}</span></div>`).join('')||'<div class="empty">No notifications yet.</div>'}</div>`}
function reportsPage(){return `<div class="page-head"><div><div class="eyebrow">CAMPUS ANALYTICS</div><h1>Reports & insights</h1><p class="subhead">Incident mix, resolution states, and locations for the current dataset.</p></div></div>${reportMetrics()}<div class="dashboard-grid"><section class="card chart-card"><div class="card-head"><div><h2>Emergency categories</h2><p>Incidents grouped by reported type</p></div></div>${chart()}</section><section class="card"><div class="card-head"><div><h2>Campus locations</h2><p>Incident distribution by location</p></div></div>${locations()}</section></div><div style="margin-top:17px">${table()}</div>`}
function auditPage(events){return `<div class="page-head"><div><div class="eyebrow">ACCOUNTABILITY</div><h1>Audit history</h1><p class="subhead">Chronological record of emergency events and staff actions.</p></div></div><div class="table-card card"><div class="card-head"><div><h2>Recent audit events</h2><p>Most recent 200 system events</p></div></div><div class="table-scroll"><table class="incident-table"><thead><tr><th>Time</th><th>Event</th><th>Actor</th><th>Incident</th><th>Details</th></tr></thead><tbody>${events.map(e=>`<tr ${e.incident_id?`data-open="${esc(e.incident_id)}"`:''}><td>${fmtDate(e.created_at)} · ${fmtTime(e.created_at)}</td><td><span class="type-pill">${esc(e.action.replaceAll('_',' '))}</span></td><td>${esc(e.actor_id||'System')}</td><td>${esc(e.display_id||e.incident_id||'—')}</td><td>${esc(e.details||'')}</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">No audit events have been recorded.</div></td></tr>'}</tbody></table></div></div>`}
function modal(title,copy,content='',actions=''){const back=document.createElement('div');back.className='modal-backdrop';back.innerHTML=`<section class="modal"><h2>${title}</h2><p>${copy}</p>${content}<div class="modal-actions">${actions}</div></section>`;document.body.append(back);back.onclick=e=>{if(e.target===back)back.remove()};return back}
async function sos(){
 const m=modal('Send an emergency alert?',`Campus safety will be alerted first. Sending SOS requests camera and microphone access, starts visible audio and video recording for up to 60 seconds, and captures one photo. Your browser asks permission; media is captured only if access is granted.`, `<label class="info-label" for="sos-details">Optional details</label><textarea id="sos-details" rows="3" placeholder="Share anything responders should know…"></textarea><p class="sos-disclaimer" style="text-align:left;margin-top:9px">The evidence list shows audio, video, and photo capture status as it happens. A recording indicator stays on screen, and you can stop recording at any time. If you deny camera or microphone access, the SOS still sends without media.</p>`,`<button class="btn" id="stay">Go back</button><button class="btn btn-primary" id="send-sos">Send SOS & start recording →</button>`);
 $('#stay').onclick=()=>m.remove();
 $('#send-sos').onclick=async()=>{
  const detail=$('#sos-details').value,requestId=crypto.randomUUID();m.remove();const btn=$('#sos');btn.disabled=true;btn.textContent='…';
  const incidentPromise=api('/api/incidents',{method:'POST',body:JSON.stringify({client_request_id:requestId,incident_type:type,description:detail,location_name:'Location pending'})});
  let permissionPromise=null;
  if(navigator.mediaDevices?.getUserMedia&&window.MediaRecorder){
   permissionPromise=navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true},video:{facingMode:{ideal:'environment'},width:{ideal:640,max:640},height:{ideal:480,max:480},frameRate:{ideal:15,max:15}}}).then(stream=>({stream}),error=>({error}));
  }
  try{
   const d=await incidentPromise,incidentId=d.incident.id;selected=incidentId;await refresh();toast('Alert confirmed by campus safety.');page='student';await render();
   if(permissionPromise)permissionPromise.then(result=>{if(result.stream){if(cancelledCaptures.has(incidentId)){result.stream.getTracks().forEach(track=>track.stop());return}startSosCapture(result.stream,incidentId)}else toast('SOS was sent, but camera or microphone permission was denied.',true)});
   else toast('SOS was sent. This browser does not support audio/video recording.',true);
   if(navigator.geolocation)navigator.geolocation.getCurrentPosition(async pos=>{try{await api(`/api/incidents/${encodeURIComponent(incidentId)}/location`,{method:'POST',body:JSON.stringify({latitude:pos.coords.latitude,longitude:pos.coords.longitude,accuracy:pos.coords.accuracy,location_name:'Shared device location'})});await refresh();if(selected===incidentId)await render()}catch{}},()=>{}, {enableHighAccuracy:true,timeout:7000,maximumAge:30000});
  }catch(e){permissionPromise?.then(result=>result.stream?.getTracks().forEach(track=>track.stop()));if(e instanceof TypeError||navigator.onLine===false){const q=JSON.parse(localStorage.getItem('campus_pending_alerts')||'[]');q.push({client_request_id:requestId,incident_type:type,description:detail,location_name:'Location pending',queued_at:new Date().toISOString()});localStorage.setItem('campus_pending_alerts',JSON.stringify(q));toast(`Not delivered. Saved on this device; call ${SOS_PHONE} for immediate help.`,true);page='student';render()}else toast(`Alert not confirmed: ${e.message}`,true);btn.disabled=false;btn.textContent='SOS'}
 };
}
async function retryQueued(){if(!token||!navigator.onLine||user?.role!=='student')return;let q=JSON.parse(localStorage.getItem('campus_pending_alerts')||'[]');if(!q.length)return;for(const item of q.slice()){try{await api('/api/incidents',{method:'POST',body:JSON.stringify(item)});q=q.filter(x=>x.client_request_id!==item.client_request_id);localStorage.setItem('campus_pending_alerts',JSON.stringify(q));toast('A queued alert is now confirmed as received by campus safety.')}catch{return}}await refresh();if(page==='student')render()}
async function action(name){const i=incidents.find(x=>x.id===selected);if(!i)return;const labels={acknowledge:['Acknowledge incident','Confirm that your team has received this alert.'],assign:['Assign responder','Record who is handling this response.'],respond:['Mark as responding','This will update the incident timeline and student status.'],arrive:['Confirm responder arrival','Record that the assigned responder has reached the location.'],resolve:['Resolve this incident','Add a short outcome note. This will be included in the permanent incident timeline.'],cancel:['Request cancellation','Your cancellation remains in the audit trail and is visible to campus responders.']};const [title,copy]=labels[name];let extra=name==='assign'?`<label class="info-label">Responder name</label><input id="action-note" placeholder="Name of responder">`:['resolve','cancel'].includes(name)?`<label class="info-label">${name==='resolve'?'Resolution notes':'Reason (optional)'}</label><textarea id="action-note" rows="3" placeholder="Add a note…"></textarea>`:'';const m=modal(title,copy,extra,`<button class="btn" id="action-back">Back</button><button class="btn ${['resolve','cancel'].includes(name)?'btn-danger':'btn-primary'}" id="action-go">${name==='cancel'?'Request cancellation':'Confirm'}</button>`);$('#action-back').onclick=()=>m.remove();$('#action-go').onclick=async()=>{try{await api(`/api/incidents/${encodeURIComponent(i.id)}/${name}`,{method:'POST',body:JSON.stringify({responder:$('#action-note')?.value,notes:$('#action-note')?.value})});if(name==='cancel'){cancelledCaptures.add(i.id);if(sosCapture?.incidentId===i.id)await stopSosCapture()}m.remove();toast(name==='resolve'?'Incident resolved and timeline updated.':'Incident updated.');await refresh();await render()}catch(e){toast(e.message,true)}}}
async function refresh(){if(!token)return;try{const r=await api('/api/incidents');incidents=r.incidents;if(user.role!=='student')dashboard=await api('/api/admin/dashboard')}catch(e){if(/sign in/i.test(e.message))logout()}}
async function openIncident(id){try{const d=await api(`/api/incidents/${encodeURIComponent(id)}`);selected=d.incident.id;await render()}catch(e){toast(e.message,true)}}
async function render(){if(!user||!token)return login();await refresh();if(selected){const r=await api(`/api/incidents/${encodeURIComponent(selected)}`).catch(()=>null);if(!r){selected=null;return render()}const d=r.incident;currentIncident=d;app.innerHTML=shell(detailPage(d));bind();return}currentIncident=null;let content;if(page==='audit'){try{content=auditPage((await api('/api/admin/audit')).events)}catch(e){content=`<div class="empty">${esc(e.message)}</div>`}}else content=page==='student'?studentPage():page==='incidents'?incidentsPage():page==='notifications'?notificationsPage():page==='reports'?reportsPage():dashboardPage();app.innerHTML=shell(content);bind()}
async function logout(){if(sosCapture)await stopSosCapture();const oldToken=token;try{await fetch('/api/auth/logout',{method:'POST',headers:{Authorization:`Bearer ${oldToken}`}})}catch{}token='';user=null;selected=null;currentIncident=null;localStorage.removeItem('campus_token');localStorage.removeItem('campus_user');login()}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{selected=null;page=b.dataset.page;render()});$('#logout')?.addEventListener('click',logout);$('#bell')?.addEventListener('click',()=>{page='notifications';selected=null;render()});$('#sos')?.addEventListener('click',sos);document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{type=b.dataset.type;render()});document.querySelectorAll('[data-open]').forEach(x=>x.onclick=()=>openIncident(x.dataset.open));$('#refresh')?.addEventListener('click',()=>render());$('#back')?.addEventListener('click',()=>{selected=null;page='incidents';render()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-evidence-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-evidence-tab]').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#evidence-list').innerHTML=evidenceList(currentIncident?.evidence||[],b.dataset.evidenceTab);bindDownloads()});bindDownloads();$('#upload-photo')?.addEventListener('click',()=>$('#media-file').click());$('#media-file')?.addEventListener('change',async e=>{const f=e.target.files[0];if(f)await uploadBlob(f,f.type.startsWith('audio/')?'audio':f.type.startsWith('video/')?'video':'photo');e.target.value=''});$('#record-audio')?.addEventListener('click',recordAudio);$('#add-note')?.addEventListener('click',async()=>{const m=modal('Add a note','Share optional context with authorized campus responders.',`<textarea id="student-note" rows="4" placeholder="Write your note…"></textarea>`,`<button class="btn" id="note-back">Cancel</button><button class="btn btn-primary" id="note-send">Add note</button>`);$('#note-back').onclick=()=>m.remove();$('#note-send').onclick=async()=>{const v=$('#student-note').value;if(!v.trim())return toast('Add a note first.',true);try{await api(`/api/incidents/${encodeURIComponent(selected)}/evidence`,{method:'POST',body:JSON.stringify({type:'text',filename:'Student note',description:v})});m.remove();toast('Your note was added.');await render()}catch(e){toast(e.message,true)}}});['search','status-filter','type-filter','officer-filter'].forEach(id=>$('#'+id)?.addEventListener(id==='search'?'input':'change',filterTable))}
document.addEventListener('click',e=>{if(e.target.closest('#logout-top'))logout()});
function bindDownloads(){document.querySelectorAll('[data-download]').forEach(b=>b.onclick=async e=>{e.stopPropagation();try{const r=await fetch(`/api/evidence/${encodeURIComponent(b.dataset.download)}`,{headers:{Authorization:`Bearer ${token}`}});if(!r.ok)throw Error('Evidence download was denied.');const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='campus-evidence';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){toast(e.message,true)}});document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=async e=>{e.stopPropagation();if(b.dataset.opened==='true')return;try{b.textContent='Loading…';const r=await fetch(`/api/evidence/${encodeURIComponent(b.dataset.preview)}`,{headers:{Authorization:`Bearer ${token}`}});if(!r.ok)throw Error('Evidence preview was denied.');const source=await r.blob(),kind=b.dataset.previewType,mime=kind==='audio'?'audio/webm':kind==='video'?'video/webm':'image/jpeg',blob=new Blob([source],{type:mime}),url=URL.createObjectURL(blob),wrap=document.createElement('div');wrap.className='evidence-preview';let media;if(kind==='audio'){media=document.createElement('audio');media.controls=true}else if(kind==='video'){media=document.createElement('video');media.controls=true;media.playsInline=true}else{media=document.createElement('img');media.alt='SOS photo evidence'}media.src=url;wrap.append(media);b.closest('.evidence-row').after(wrap);b.textContent='Loaded';b.dataset.opened='true'}catch(e){b.textContent='Preview';toast(e.message,true)}})}
function captureIndicator(message,uploading=false){let el=$('#sos-recording-indicator');if(!el){el=document.createElement('div');el.id='sos-recording-indicator';el.className='sos-recording-indicator';document.body.append(el)}el.innerHTML=`<span class="recording-dot"></span><span>${esc(message)}</span>${uploading?'':'<button type="button" id="stop-sos-capture">Stop recording</button>'}`;if(!uploading)$('#stop-sos-capture').onclick=stopSosCapture;return el}
async function captureStill(stream){const video=document.createElement('video');video.muted=true;video.playsInline=true;video.autoplay=true;video.style.cssText='position:fixed;width:2px;height:2px;left:-10px;top:0;opacity:.01;pointer-events:none';video.srcObject=stream;document.body.append(video);const timeout=(promise,label,ms=5000)=>Promise.race([promise,new Promise((_,reject)=>setTimeout(()=>reject(Error(`${label} timed out.`)),ms))]);try{if(video.readyState<2){const frame=new Promise((resolve,reject)=>{video.addEventListener('loadeddata',resolve,{once:true});video.addEventListener('error',()=>reject(Error('Camera frame could not be read.')),{once:true})});await timeout(Promise.all([video.play(),frame]),'Camera photo capture')}const settings=stream.getVideoTracks()[0]?.getSettings()||{},canvas=document.createElement('canvas');canvas.width=Math.min(settings.width||640,640);canvas.height=Math.min(settings.height||480,480);const context=canvas.getContext('2d');if(!context||!video.videoWidth)throw Error('The camera did not provide a photo frame.');context.drawImage(video,0,0,canvas.width,canvas.height);return await timeout(new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.72)),'Photo encoding')}finally{video.pause();video.srcObject=null;video.remove()}}
async function setCaptureEvidenceStatus(incidentId,evidenceId,type,status,description='Automatic SOS capture'){if(!evidenceId)return;await api(`/api/incidents/${encodeURIComponent(incidentId)}/evidence`,{method:'POST',body:JSON.stringify({evidence_id:evidenceId,type,filename:`SOS ${type} capture`,upload_status:status,description})})}
